// Mock IndexedDB for testing
class MockIDBRequest {
  constructor() {
    this.result = null;
    this.error = null;
    this.onsuccess = null;
    this.onerror = null;
    this.onupgradeneeded = null;
  }

  _triggerSuccess(result) {
    this.result = result;
    if (this.onsuccess) this.onsuccess({ target: { result } });
  }

  _triggerUpgradeNeeded(oldVersion, newVersion, db) {
    if (this.onupgradeneeded) {
      this.onupgradeneeded({
        target: { result: db },
        oldVersion,
        newVersion
      });
    }
  }
}

class MockIDBDatabase {
  constructor(name, version) {
    this.name = name;
    this.version = version;
    this.objectStoreNames = {
      _stores: new Set(),
      contains(name) {
        return this._stores.has(name);
      }
    };
    this._createdStores = [];
  }

  createObjectStore(name) {
    this.objectStoreNames._stores.add(name);
    this._createdStores.push(name);
    return {};
  }

  transaction() {
    return {
      objectStore: () => ({})
    };
  }
}

class MockIndexedDB {
  constructor() {
    this.databases = new Map();
    this.openCalls = [];
  }

  open(name, version) {
    this.openCalls.push({ name, version });

    const request = new MockIDBRequest();

    // Simulate async behavior
    setTimeout(() => {
      let db = this.databases.get(name);
      const oldVersion = db ? db.version : 0;

      if (!db || (version && version > db.version)) {
        // Create new or upgrade database
        db = new MockIDBDatabase(name, version || 1);
        this.databases.set(name, db);

        // Copy existing stores if upgrading
        if (oldVersion > 0) {
          const oldDb = this.databases.get(name);
          if (oldDb) {
            oldDb.objectStoreNames._stores.forEach(store => {
              db.objectStoreNames._stores.add(store);
            });
          }
        }

        // Trigger onupgradeneeded
        request._triggerUpgradeNeeded(oldVersion, version || 1, db);
      }

      // Always trigger success after upgrade
      request._triggerSuccess(db);
    }, 10);

    return request;
  }

  reset() {
    this.databases.clear();
    this.openCalls = [];
  }
}

