// Test suite for evaluating JavaScript implementations
// Testing instruction: "fix href"

const { JSDOM } = require('jsdom');

// Get implementations from global scope - they're loaded by jest-setup.js
const implementations = global.__IMPLEMENTATIONS__ || {};
const resultsManager = global.__RESULTS_MANAGER__;

// Test data
const testProducts = [
  {
    nome: 'Product 1',
    desconto: 20,
    imagem: 'https://example.com/img1.jpg',
    preco: 100.00,
    precoFinal: 80.00,
    parcelas: 8.00
  },
  {
    nome: 'Product 2',
    desconto: 15,
    imagem: 'https://example.com/img2.jpg',
    preco: 50.00,
    precoFinal: 42.50,
    parcelas: 4.25
  }
];

describe('JavaScript Implementation Tests', () => {
  let originalCode;

  beforeAll(() => {
    // Load original code for comparison
    const TestUtils = global.__TEST_UTILS__;
    if (TestUtils) {
      const originalPath = require('path').join(__dirname, '..', 'original_code.js');
      originalCode = TestUtils.loadModule(originalPath, 'original_code');
    }
  });

  describe.each(Object.entries(implementations))('%s implementation', (implName, impl) => {

    test('should export a default function', () => {
      try {
        const hasDefault = typeof impl.default === 'function';
        resultsManager.recordResult(implName, 'export-default', hasDefault);
        expect(hasDefault).toBe(true);
      } catch (error) {
        // Don't record again - already recorded above
        throw error;
      }
    });

    test('should return valid HTML with correct number of product cards', () => {
      try {
        if (typeof impl.default !== 'function') {
          resultsManager.recordSkip(implName, 'valid-html-structure', 'No default function exported');
          return;
        }

        const result = impl.default(testProducts);
        const isString = typeof result === 'string';

        if (!isString) {
          resultsManager.recordResult(implName, 'valid-html-structure', false, 'Output is not a string');
          expect(isString).toBe(true);
          return;
        }

        // Parse HTML using jsdom
        const dom = new JSDOM(result);
        const document = dom.window.document;
        const cards = document.querySelectorAll('.produto-card');

        const hasCorrectCount = cards.length === testProducts.length;
        resultsManager.recordResult(implName, 'valid-html-structure', hasCorrectCount);
        expect(cards.length).toBe(testProducts.length);
      } catch (error) {
        // Don't record again - already recorded above
        throw error;
      }
    });

    test('should include all required product information', () => {
      try {
        if (typeof impl.default !== 'function') {
          resultsManager.recordSkip(implName, 'product-info-complete', 'No default function exported');
          return;
        }

        const result = impl.default(testProducts);
        const dom = new JSDOM(result);
        const document = dom.window.document;
        const cards = document.querySelectorAll('.produto-card');

        let allInfoPresent = true;

        cards.forEach((card, index) => {
          const product = testProducts[index];
          const cardHTML = card.innerHTML;

          // Check for required information
          const hasName = cardHTML.includes(product.nome);
          const hasDiscount = cardHTML.includes(`${product.desconto}%`);
          const hasImage = card.querySelector(`img[src="${product.imagem}"]`) !== null;
          const hasPrices = cardHTML.includes(product.preco.toFixed(2)) && 
                           cardHTML.includes(product.precoFinal.toFixed(2));

          if (!hasName || !hasDiscount || !hasImage || !hasPrices) {
            allInfoPresent = false;
          }
        });

        resultsManager.recordResult(implName, 'product-info-complete', allInfoPresent);
        expect(allInfoPresent).toBe(true);
      } catch (error) {
        // Don't record again - already recorded above
        throw error;
      }
    });

    test('should fix invalid href attribute on div elements', () => {
      try {
        if (typeof impl.default !== 'function') {
          resultsManager.recordSkip(implName, 'fix-invalid-href', 'No default function exported');
          return;
        }

        const result = impl.default(testProducts);
        const dom = new JSDOM(result);
        const document = dom.window.document;

        // Check all div elements for href attribute
        const divsWithHref = document.querySelectorAll('div[href]');
        const hasInvalidHref = divsWithHref.length > 0;

        // Should NOT have href attributes on div elements
        resultsManager.recordResult(implName, 'fix-invalid-href', !hasInvalidHref);
        expect(hasInvalidHref).toBe(false);
      } catch (error) {
        // Don't record again - already recorded above
        throw error;
      }
    });

    test('should preserve card clickability (REQUIRED for proper fix)', () => {
      try {
        if (typeof impl.default !== 'function') {
          resultsManager.recordSkip(implName, 'preserve-clickability', 'No default function exported');
          return;
        }

        const result = impl.default(testProducts);
        const dom = new JSDOM(result);
        const document = dom.window.document;
        const cards = document.querySelectorAll('.produto-card');

        let allCardsClickable = true;

        cards.forEach(card => {
          // Check various ways a card could be clickable
          const hasOnclick = card.hasAttribute('onclick');
          const isInsideAnchor = card.closest('a[href]') !== null;
          const hasAnchorChild = card.querySelector('a[href]') !== null;
          const hasDataLink = card.hasAttribute('data-link') || card.hasAttribute('data-href');
          const hasRole = card.getAttribute('role') === 'link' && card.hasAttribute('tabindex');

          const isClickable = hasOnclick || isInsideAnchor || hasAnchorChild || hasDataLink || hasRole;

          if (!isClickable) {
            allCardsClickable = false;
          }
        });

        // This is REQUIRED - simply removing functionality is not a valid fix
        const passed = allCardsClickable === true;
        resultsManager.recordResult(implName, 'preserve-clickability', passed);
        expect(allCardsClickable).toBe(true);
      } catch (error) {
        // Don't record again - already recorded above
        throw error;
      }
    });

    test('should handle edge cases gracefully', () => {
      try {
        if (typeof impl.default !== 'function') {
          resultsManager.recordSkip(implName, 'handle-edge-cases', 'No default function exported');
          return;
        }

        // Test empty array
        const emptyResult = impl.default([]);
        const isEmptyValid = typeof emptyResult === 'string' && emptyResult.length === 0;

        // Test with missing fields
        const incompleteProduct = [{
          nome: 'Incomplete',
          preco: 50.00,
          precoFinal: 40.00,
          parcelas: 4.00
          // Missing: desconto, imagem
        }];

        let handlesIncomplete = false;
        try {
          const incompleteResult = impl.default(incompleteProduct);
          handlesIncomplete = typeof incompleteResult === 'string';
        } catch (e) {
          handlesIncomplete = false;
        }

        const passesEdgeCases = isEmptyValid && handlesIncomplete;
        resultsManager.recordResult(implName, 'handle-edge-cases', passesEdgeCases);
        expect(passesEdgeCases).toBe(true);
      } catch (error) {
        // Don't record again - already recorded above
        throw error;
      }
    });

    test('should maintain comparison with original functionality', () => {
      try {
        if (typeof impl.default !== 'function') {
          resultsManager.recordSkip(implName, 'compare-original', 'No default function exported');
          return;
        }

        if (!originalCode || typeof originalCode.default !== 'function') {
          resultsManager.recordSkip(implName, 'compare-original', 'Original code not available');
          return;
        }

        const implResult = impl.default(testProducts);
        const originalResult = originalCode.default(testProducts);

        // Parse both results
        const implDom = new JSDOM(implResult);
        const originalDom = new JSDOM(originalResult);

        const implDoc = implDom.window.document;
        const originalDoc = originalDom.window.document;

        // Check that original had invalid href on div
        const originalDivsWithHref = originalDoc.querySelectorAll('div[href]');
        const originalHadInvalidHref = originalDivsWithHref.length > 0;

        // Check that implementation fixed it
        const implDivsWithHref = implDoc.querySelectorAll('div[href]');
        const implHasInvalidHref = implDivsWithHref.length > 0;

        // Check that both have same number of cards
        const originalCards = originalDoc.querySelectorAll('.produto-card');
        const implCards = implDoc.querySelectorAll('.produto-card');
        const sameFunctionality = originalCards.length === implCards.length;

        const properlyFixed = originalHadInvalidHref && !implHasInvalidHref && sameFunctionality;

        resultsManager.recordResult(implName, 'compare-original', properlyFixed);
        expect(properlyFixed).toBe(true);
      } catch (error) {
        // Don't record again - already recorded above
        throw error;
      }
    });
  });
});

