  Object.values(elementCache).forEach(el => {
    if (el.text && el.text.mockClear) el.text.mockClear();
    if (el.css && el.css.mockClear) el.css.mockClear();
    if (el.fadeOut && el.fadeOut.mockClear) el.fadeOut.mockClear();
    if (el.fadeIn && el.fadeIn.mockClear) el.fadeIn.mockClear();
  });

  jquery.each.mockClear();
  jquery.parseJSON.mockClear();
