class GlobeInstance {
  constructor(domElement) {
    this._domElement = domElement;
    this._properties = {
      globeImageUrl: '',
      bumpImageUrl: '',
      backgroundImageUrl: '',
      polygonsData: [],
      polygonAltitude: 0,
      polygonCapColor: null,
      polygonSideColor: null,
      polygonStrokeColor: null,
      polygonLabel: null,
      polygonsTransitionDuration: 0,
      lineHoverPrecision: 0
    };
    this._globeMaterial = {
      specularMap: null,
      specular: null,
      shininess: 0
    };
    this._lights = [
      { type: 'AmbientLight' },
      { type: 'DirectionalLight', position: { set: jest.fn() } }
    ];
    this._countriesLayerAdded = false;
  }

  // Chainable methods
  globeImageUrl(url) {
    this._properties.globeImageUrl = url;
    return this;
  }

  bumpImageUrl(url) {
    this._properties.bumpImageUrl = url;
    return this;
  }

  backgroundImageUrl(url) {
    this._properties.backgroundImageUrl = url;
    return this;
  }

  globeMaterial() {
    return this._globeMaterial;
  }

  lights() {
    return this._lights;
  }

  polygonsData(data) {
    this._properties.polygonsData = data;
    this._countriesLayerAdded = true;
    return this;
  }

  polygonAltitude(altitude) {
    if (typeof altitude === 'function') {
      this._properties.polygonAltitudeFunc = altitude;
    } else {
      this._properties.polygonAltitude = altitude;
    }
    return this;
  }

  polygonCapColor(colorFn) {
    this._properties.polygonCapColor = colorFn;
    return this;
  }

  polygonSideColor(colorFn) {
    this._properties.polygonSideColor = colorFn;
    return this;
  }

  polygonStrokeColor(colorFn) {
    this._properties.polygonStrokeColor = colorFn;
    return this;
  }

  polygonLabel(labelFn) {
    this._properties.polygonLabel = labelFn;
    return this;
  }

  onPolygonHover(hoverFn) {
    this._properties.onPolygonHover = hoverFn;
    return this;
  }

  polygonsTransitionDuration(duration) {
    this._properties.polygonsTransitionDuration = duration;
    return this;
  }

  lineHoverPrecision(precision) {
    this._properties.lineHoverPrecision = precision;
    return this;
  }

  // Allow checking if countries layer was added
  hasCountriesLayer() {
    return this._countriesLayerAdded;
  }
}

function Globe(domElement) {
  const instance = new GlobeInstance(domElement);

  // Make the instance callable to support the syntax:
  // Globe()....(domElement)
  const callable = function(domElement) {
    instance._domElement = domElement;
    return instance;
  };

  // Copy all properties and methods from instance to callable
  Object.setPrototypeOf(callable, instance);
  Object.getOwnPropertyNames(GlobeInstance.prototype).forEach(name => {
    if (name !== 'constructor') {
      callable[name] = instance[name].bind(instance);
    }
  });

  return callable;
}

module.exports = Globe;

