function scaleSequentialSqrt(interpolator) {
  const scale = {
    domain: function(domain) {
      scale._domain = domain;
      return scale;
    },
    _domain: [0, 1],
    _interpolator: interpolator,
    __type__: 'scaleSequentialSqrt'
  };

  // Make the scale callable
  const fn = (value) => {
    // Simple linear mapping from domain to range [0, 1]
    if (scale._domain[0] === scale._domain[1]) return 0.5;
    const normalized = (value - scale._domain[0]) / (scale._domain[1] - scale._domain[0]);
    return Math.max(0, Math.min(1, normalized));
  };

  // Copy properties from scale to fn
  Object.setPrototypeOf(fn, scale);
  return fn;
}

