        console.error(`Syntax error in ${filePath}: ${e.message}`);

        // Record the error but continue loading what we can
        moduleObj.__errors__.push({
          type: 'syntax',
          message: errorMsg,
          lineNumber: e.loc ? e.loc.line : undefined,
