// Get implementations from global scope - they're loaded by jest-setup.js
const implementations = global.__IMPLEMENTATIONS__ || {};
const resultsManager = global.__RESULTS_MANAGER__;

// Test data
const testProducts = [
  {
    nome: 'Product 1',
    desconto: 20,
    imagem: 'https://example.com/img1.jpg',
    preco: 100.00,
    precoFinal: 80.00,
    parcelas: 8.00
  },
  {
    nome: 'Product 2',
    desconto: 15,
    imagem: 'https://example.com/img2.jpg',
    preco: 50.00,
    precoFinal: 42.50,
    parcelas: 4.25
  }
];

describe('JavaScript Implementation Tests', () => {
  let originalCode;

  beforeAll(() => {
    // Load original code for comparison
    const TestUtils = global.__TEST_UTILS__;
    if (TestUtils) {
      const originalPath = require('path').join(__dirname, '..', 'original_code.js');
      originalCode = TestUtils.loadModule(originalPath, 'original_code');
    }
  });

  describe.each(Object.entries(implementations))('%s implementation', (implName, impl) => {

    test('should export a default function', () => {
      try {
        const hasDefault = typeof impl.default === 'function';
        resultsManager.recordResult(implName, 'export-default', hasDefault);
        expect(hasDefault).toBe(true);
      } catch (error) {
        // Don't record again - already recorded above
        throw error;
      }
    });

