      try {
        if (typeof impl.default !== 'function') {
          resultsManager.recordSkip(implName, 'product-info-complete', 'No default function exported');
          return;
        }

        const result = impl.default(testProducts);
        const dom = new JSDOM(result);
        const document = dom.window.document;
        const cards = document.querySelectorAll('.produto-card');

        let allInfoPresent = true;

        cards.forEach((card, index) => {
          const product = testProducts[index];
          const cardHTML = card.innerHTML;

          // Check for required information
          const hasName = cardHTML.includes(product.nome);
          const hasDiscount = cardHTML.includes(`${product.desconto}%`);
          const hasImage = card.querySelector(`img[src="${product.imagem}"]`) !== null;
          const hasPrices = cardHTML.includes(product.preco.toFixed(2)) && 
                           cardHTML.includes(product.precoFinal.toFixed(2));

          if (!hasName || !hasDiscount || !hasImage || !hasPrices) {
            allInfoPresent = false;
          }
        });

        resultsManager.recordResult(implName, 'product-info-complete', allInfoPresent);
        expect(allInfoPresent).toBe(true);
      } catch (error) {
        // Don't record again - already recorded above
        throw error;
      }
    });

