      ${functionCode}
      module.exports = { createTurnState };
    `;

    // Create a temporary file with the evaluated code
    const tempDir = path.dirname(filePath);
    const tempFile = path.join(tempDir, `__temp_${path.basename(filePath)}`);
    fs.writeFileSync(tempFile, wrapperCode);

    // Load the module
    const module = require(tempFile);

    // Clean up
    fs.unlinkSync(tempFile);

    return module;
  } catch (e) {
    console.error(`Error loading ES module ${filePath}:`, e);
    return { __errors__: [e.message] };
  }
}

