// Testing instruction: "fix href"

const { JSDOM } = require('jsdom');

// Get implementations from global scope - they're loaded by jest-setup.js
const implementations = global.__IMPLEMENTATIONS__ || {};
const resultsManager = global.__RESULTS_MANAGER__;

// Test data
const testProducts = [
  {
    nome: 'Product 1',
    desconto: 20,
    imagem: 'https://example.com/img1.jpg',
    preco: 100.00,
    precoFinal: 80.00,
    parcelas: 8.00
  },
  {
    nome: 'Product 2',
    desconto: 15,
    imagem: 'https://example.com/img2.jpg',
    preco: 50.00,
    precoFinal: 42.50,
    parcelas: 4.25
  }
];

describe('JavaScript Implementation Tests', () => {
  let originalCode;

  beforeAll(() => {
    // Load original code for comparison
    const TestUtils = global.__TEST_UTILS__;
    if (TestUtils) {
      const originalPath = require('path').join(__dirname, '..', 'original_code.js');
      originalCode = TestUtils.loadModule(originalPath, 'original_code');
    }
  });

  describe.each(Object.entries(implementations))('%s implementation', (implName, impl) => {

    test('should export a default function', () => {
      try {
        const hasDefault = typeof impl.default === 'function';
        resultsManager.recordResult(implName, 'export-default', hasDefault);
        expect(hasDefault).toBe(true);
      } catch (error) {
        // Don't record again - already recorded above
        throw error;
      }
    });

    test('should return valid HTML with correct number of product cards', () => {
      try {
        if (typeof impl.default !== 'function') {
          resultsManager.recordSkip(implName, 'valid-html-structure', 'No default function exported');
          return;
        }

        const result = impl.default(testProducts);
        const isString = typeof result === 'string';

        if (!isString) {
          resultsManager.recordResult(implName, 'valid-html-structure', false, 'Output is not a string');
          expect(isString).toBe(true);
          return;
        }

        // Parse HTML using jsdom
        const dom = new JSDOM(result);
        const document = dom.window.document;
        const cards = document.querySelectorAll('.produto-card');

        const hasCorrectCount = cards.length === testProducts.length;
        resultsManager.recordResult(implName, 'valid-html-structure', hasCorrectCount);
        expect(cards.length).toBe(testProducts.length);
      } catch (error) {
        // Don't record again - already recorded above
        throw error;
      }
    });

    test('should include all required product information', () => {
      try {
        if (typeof impl.default !== 'function') {
          resultsManager.recordSkip(implName, 'product-info-complete', 'No default function exported');
          return;
        }

        const result = impl.default(testProducts);
        const dom = new JSDOM(result);
        const document = dom.window.document;
        const cards = document.querySelectorAll('.produto-card');

        let allInfoPresent = true;

        cards.forEach((card, index) => {
          const product = testProducts[index];
          const cardHTML = card.innerHTML;

          // Check for required information
          const hasName = cardHTML.includes(product.nome);
          const hasDiscount = cardHTML.includes(`${product.desconto}%`);
          const hasImage = card.querySelector(`img[src="${product.imagem}"]`) !== null;
          const hasPrices = cardHTML.includes(product.preco.toFixed(2)) && 
                           cardHTML.includes(product.precoFinal.toFixed(2));

          if (!hasName || !hasDiscount || !hasImage || !hasPrices) {
            allInfoPresent = false;
          }
