            model = convnet_class()
        except Exception as e:
            pytest.skip(f"{impl_name}: Failed to create model instance: {e}")

    # Check conv1 structure
    assert hasattr(model, "conv1"), f"{impl_name}: Missing conv1 layer"
    assert isinstance(
