// jQuery mock
const elementCache = {};
const clickHandlers = {};

const jquery = function(selector) {
  // Cache elements to ensure the same mock instance is returned for the same selector
  if (!elementCache[selector]) {
    elementCache[selector] = {
      selector,
      ready: function(callback) {
        if (typeof callback === 'function') {
          // Store the callback for later execution
          if (!jquery.readyCallbacks) {
            jquery.readyCallbacks = [];
          }
          jquery.readyCallbacks.push(callback);
        }
        return this;
      },
      text: jest.fn(function(value) {
        if (value !== undefined) {
          this.textValue = value;
          return this;
        }
        return this.textValue || '';
      }),
      css: jest.fn(function(prop, value) {
        if (!this.cssProps) this.cssProps = {};
        this.cssProps[prop] = value;
        return this;
      }),
      fadeOut: jest.fn(function(duration) {
        return this;
      }),
      fadeIn: jest.fn(function(duration) {
        return this;
      }),
      click: function(callback) {
        clickHandlers[selector] = callback;
        return this;
      },
      // Method to trigger the click handler
      triggerClick: function() {
        if (typeof clickHandlers[selector] === 'function') {
          clickHandlers[selector]();
        }
        return this;
      }
    };
  }

  return elementCache[selector];
};

// Helper to execute all ready callbacks
jquery.executeReady = function() {
  if (jquery.readyCallbacks) {
    jquery.readyCallbacks.forEach(callback => {
      try {
        callback();
      } catch (e) {
        console.error('Error in ready callback:', e);
      }
    });
  }
};

// Extend $ with utility methods
jquery.each = jest.fn((obj, callback) => {
  if (obj && typeof callback === 'function') {
    Object.entries(obj).forEach(([key, value]) => {
      callback(key, value);
    });
  }
});

jquery.parseJSON = jest.fn((data) => {
  // This method is deprecated in jQuery - this should cause a test failure
  try {
    return JSON.parse(data);
  } catch (e) {
    throw new Error('Invalid JSON');
  }
});

// Reset mock function to clear counters
jquery.resetMocks = function() {
  Object.values(elementCache).forEach(el => {
    if (el.text && el.text.mockClear) el.text.mockClear();
    if (el.css && el.css.mockClear) el.css.mockClear();
    if (el.fadeOut && el.fadeOut.mockClear) el.fadeOut.mockClear();
    if (el.fadeIn && el.fadeIn.mockClear) el.fadeIn.mockClear();
  });

  jquery.each.mockClear();
  jquery.parseJSON.mockClear();
};

// Set global $ variable
global.$ = jquery;

// Export both as default and as named export
module.exports = jquery;

