// Find winner
const determineWinner = (results) => {
  let winner = -1;
  let maxPassed = -1;

  Object.entries(results).forEach(([implName, stats]) => {
    if (stats.passed > maxPassed) {
      maxPassed = stats.passed;
      const match = implName.match(/(\d+)/);
      if (match) {
        winner = parseInt(match[1], 10);
      }
    }
  });

  return winner;
};

