          precoFinal: 40.00,
          parcelas: 4.00
          // Missing: desconto, imagem
        }];

        let handlesIncomplete = false;
        try {
          const incompleteResult = impl.default(incompleteProduct);
          handlesIncomplete = typeof incompleteResult === 'string';
        } catch (e) {
          handlesIncomplete = false;
        }

        const passesEdgeCases = isEmptyValid && handlesIncomplete;
        resultsManager.recordResult(implName, 'handle-edge-cases', passesEdgeCases);
        expect(passesEdgeCases).toBe(true);
      } catch (error) {
        // Don't record again - already recorded above
        throw error;
      }
    });

    test('should maintain comparison with original functionality', () => {
      try {
        if (typeof impl.default !== 'function') {
          resultsManager.recordSkip(implName, 'compare-original', 'No default function exported');
          return;
        }

        if (!originalCode || typeof originalCode.default !== 'function') {
          resultsManager.recordSkip(implName, 'compare-original', 'Original code not available');
          return;
        }

        const implResult = impl.default(testProducts);
        const originalResult = originalCode.default(testProducts);

        // Parse both results
        const implDom = new JSDOM(implResult);
        const originalDom = new JSDOM(originalResult);

        const implDoc = implDom.window.document;
        const originalDoc = originalDom.window.document;

        // Check that original had invalid href on div
        const originalDivsWithHref = originalDoc.querySelectorAll('div[href]');
        const originalHadInvalidHref = originalDivsWithHref.length > 0;

        // Check that implementation fixed it
        const implDivsWithHref = implDoc.querySelectorAll('div[href]');
        const implHasInvalidHref = implDivsWithHref.length > 0;

        // Check that both have same number of cards
        const originalCards = originalDoc.querySelectorAll('.produto-card');
        const implCards = implDoc.querySelectorAll('.produto-card');
        const sameFunctionality = originalCards.length === implCards.length;

        const properlyFixed = originalHadInvalidHref && !implHasInvalidHref && sameFunctionality;

        resultsManager.recordResult(implName, 'compare-original', properlyFixed);
        expect(properlyFixed).toBe(true);
      } catch (error) {
        // Don't record again - already recorded above
        throw error;
      }
    });
