    # Check if any CNN class exists
    assert (
        convnet_class is not None
    ), f"{impl_name}: No CNN class found. Make sure your class inherits from nn.Module and has a typical CNN structure."

    # Check if it's a subclass of nn.Module
    assert any(
        "Module" in str(base) for base in convnet_class.__mro__
    ), f"{impl_name}: CNN class should inherit from nn.Module"


def test_conv_layers_structure(implementation):
    """Test the convolutional layers structure of the model."""
