        criterion = torch.nn.CrossEntropyLoss()
        optimizer = torch.optim.SGD(model.parameters(), lr=0.01)

        # Create dummy target labels (batch_size,)
        target_labels = torch.randint(0, 3, (batch_size,))

        # Forward pass
        outputs = model(input_tensor)

        # Check output shape
        assert outputs.shape == (
            batch_size,
            3,
        ), f"{impl_name}: Expected output shape {(batch_size, 3)}, got {outputs.shape}"

        # Calculate loss
        loss = criterion(outputs, target_labels)

        # Check that loss is a scalar tensor
        assert (
            loss.dim() == 0
        ), f"{impl_name}: Loss should be a scalar tensor, got dimension {loss.dim()}"
        assert not torch.isnan(loss).any(), f"{impl_name}: Loss contains NaN values"

        # Backward pass
        optimizer.zero_grad()
        loss.backward()

        # Check that gradients are computed for parameters
        any_grad = False
        for name, param in model.named_parameters():
            if param.grad is not None and torch.sum(torch.abs(param.grad)) > 0:
                any_grad = True
                break

        assert any_grad, f"{impl_name}: No gradients were computed during backward pass"

        # Optimizer step
        optimizer.step()

        # Try a second forward pass to ensure model still works after weight update
        new_outputs = model(input_tensor)
        assert new_outputs.shape == (
            batch_size,
            3,
        ), f"{impl_name}: Model failed after optimizer step"

        # Test evaluation mode
        model.eval()
        with torch.no_grad():
            eval_outputs = model(input_tensor)

        assert eval_outputs.shape == (
            batch_size,
            3,
        ), f"{impl_name}: Model failed in evaluation mode"

    except Exception as e:
        pytest.skip(f"{impl_name}: End-to-end execution failed with error: {str(e)}")

