          if (stylingTest) {
            testResults[implName].passed += 1;
          } else {
            testResults[implName].failed += 1;
          }
          testResults[implName].total += 1;

          // Test: interaction
          const interactionTest = globeInstance.onPolygonHover.mock.calls.length > 0 &&
