import pytest
import numpy as np
import io
import sys
from unittest.mock import patch, mock_open
import tempfile
import os
import importlib

def run_implementation(module, mock_input, check_exception=False):
    """Helper function to run an implementation with the given mock input."""
    with patch('builtins.open', mock_open(read_data=mock_input)):
        with patch('sys.stdout', new=io.StringIO()) as fake_out:
            # Modify the input file path to use the mock
            module.INPUT_FILE_PATH = 'mock_path.txt'

            # Check if main function exists, otherwise call the module
            if hasattr(module, 'main'):
                if check_exception:
                    try:
                        module.main()
                        return True, fake_out.getvalue()
                    except Exception as e:
                        return False, str(e)
                else:
                    module.main()
                    return fake_out.getvalue()
            else:
                # If no main function, try running the module directly
                try:
                    # This is a bit hacky but allows us to run the module as a script
                    with patch.object(sys, 'argv', ['mock_path.txt']):
                        saved_modules = set(sys.modules.keys())
                        spec = importlib.util.spec_from_file_location("temp_module", module.__file__)
                        temp_module = importlib.util.module_from_spec(spec)
                        spec.loader.exec_module(temp_module)
                        # Clean up any new modules that were imported
                        for m in set(sys.modules.keys()) - saved_modules:
                            if m != "temp_module":
                                sys.modules.pop(m, None)
                    return fake_out.getvalue()
                except Exception as e:
                    if check_exception:
                        return False, str(e)
                    raise

def test_implementation_runs(implementation):
    """Basic test to check if implementation runs without errors."""
    impl_name, module = implementation

    # Simple input that should work for all implementations
    mock_input = "ABCD\nEFGH\nIJKL\nMNOP"

    try:
        output = run_implementation(module, mock_input)
